#include <vector>
#include <limits>
#include <algorithm>
#include <omp.h>

int smallestOdd(std::vector<int> const& x) {
    int globalMin = std::numeric_limits<int>::max();

    #pragma omp parallel
    {
        int localMin = std::numeric_limits<int>::max();

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            int v = x[i];
            if ((v & 1) != 0) {               // odd (works for negative odds too)
                if (v < localMin) localMin = v;
            }
        }

        #pragma omp critical
        {
            if (localMin < globalMin) globalMin = localMin;
        }
    }

    // If no odd number exists, return INT_MAX (could be adjusted per spec).
    return globalMin;
}
